/**
 * Theo UI — Theme types.
 *
 * A Theme is a frozen bundle of CSS-var values that the runtime can swap by
 * setting `data-theme="<name>"` on `<html>`. The structure mirrors what lives
 * in tokens.css so themes can be merged without ambiguity.
 */

export type ThemeMode = "light" | "dark";

export interface ColorScale {
  background: string;
  foreground: string;
  card: string;
  "card-foreground": string;
  popover: string;
  "popover-foreground": string;
  primary: string;
  "primary-deep": string;
  "primary-glow": string;
  "primary-foreground": string;
  secondary: string;
  "secondary-foreground": string;
  accent: string;
  "accent-deep": string;
  "accent-foreground": string;
  muted: string;
  "muted-foreground": string;
  border: string;
  input: string;
  ring: string;
  success: string;
  "success-foreground": string;
  warning: string;
  "warning-foreground": string;
  destructive: string;
  "destructive-foreground": string;
  info: string;
  "info-foreground": string;
}

export interface ThemeFonts {
  /** Display headlines (h1-h3, hero text). */
  display: string;
  /** Body / UI text. */
  body: string;
  /** Code, mono, paths, timestamps. */
  mono: string;
}

export interface Theme {
  /** Stable id, used in `data-theme`. */
  name: string;
  /** Human-readable label for theme switchers. */
  label: string;
  /** Optional short description shown in switchers. */
  description?: string;
  fonts: ThemeFonts;
  light: ColorScale;
  dark: ColorScale;
  /**
   * Optional URL(s) to fetch before applying. The provider injects a `<link>`
   * tag once per URL to load remote fonts. Already-injected URLs are deduped.
   */
  fontUrls?: string[];
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import type { JSX, ReactNode } from "react";
import type { ColorScale, Theme, ThemeMode } from "@/themes/types";
import { violetForge } from "@/themes/violet-forge";

interface ThemeContextValue {
  /** Active theme (full descriptor). */
  theme: Theme;
  /** Active mode: light or dark. */
  mode: ThemeMode;
  /** All available themes. */
  themes: Theme[];
  /** Swap the active theme by name. */
  setTheme: (name: string) => void;
  /** Set light/dark explicitly. */
  setMode: (mode: ThemeMode) => void;
  /** Toggle light <> dark. */
  toggleMode: () => void;
  /** Register an additional theme at runtime. */
  registerTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

const STYLE_ELEMENT_ID = "theo-ui-theme-vars";

function colorScaleToCss(name: string, mode: ThemeMode, colors: ColorScale): string {
  const selector =
    mode === "light"
      ? `[data-theme="${name}"]`
      : `[data-theme="${name}"].dark, [data-theme="${name}"][data-mode="dark"]`;
  const decls = Object.entries(colors)
    .map(([token, value]) => `  --${token}: ${value};`)
    .join("\n");
  return `${selector} {\n${decls}\n}`;
}

function fontsToCss(name: string, fonts: Theme["fonts"]): string {
  return `[data-theme="${name}"] {\n  --font-display: ${fonts.display};\n  --font-body: ${fonts.body};\n  --font-mono: ${fonts.mono};\n}`;
}

function injectThemeCss(themes: Theme[]): void {
  if (typeof document === "undefined") return;
  let style = document.getElementById(STYLE_ELEMENT_ID) as HTMLStyleElement | null;
  if (!style) {
    style = document.createElement("style");
    style.id = STYLE_ELEMENT_ID;
    document.head.appendChild(style);
  }
  const blocks: string[] = [];
  for (const theme of themes) {
    blocks.push(fontsToCss(theme.name, theme.fonts));
    blocks.push(colorScaleToCss(theme.name, "light", theme.light));
    blocks.push(colorScaleToCss(theme.name, "dark", theme.dark));
  }
  style.textContent = blocks.join("\n\n");
}

const injectedFontUrls = new Set<string>();

function loadThemeFonts(theme: Theme): void {
  if (typeof document === "undefined") return;
  if (!theme.fontUrls) return;
  for (const url of theme.fontUrls) {
    if (injectedFontUrls.has(url)) continue;
    injectedFontUrls.add(url);
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;
    document.head.appendChild(link);
  }
}

interface ThemeProviderProps {
  children: ReactNode;
  /** Theme to start with. Defaults to `violet-forge`. */
  defaultTheme?: string;
  /** Mode to start with. Defaults to `light`. */
  defaultMode?: ThemeMode;
  /**
   * Available themes. Always includes `violet-forge` even if omitted.
   * Pass extra Theme objects to register them.
   */
  themes?: Theme[];
  /**
   * Persist selection in localStorage under this key. Pass `null` to disable.
   * Default: "theo-ui:theme".
   */
  storageKey?: string | null;
}

/**
 * ThemeProvider — central registry + runtime switcher for Theo themes.
 *
 * Behavior:
 *   1. On mount, injects a `<style id="theo-ui-theme-vars">` element with
 *      one CSS block per theme (`[data-theme="<name>"] { --token: ... }`).
 *   2. Sets `data-theme` and `data-mode` on `<html>` so any element nested
 *      below inherits the right tokens (the Tailwind config consumes them).
 *   3. Lazy-loads theme font URLs by injecting `<link rel="stylesheet">`.
 *   4. Optionally persists choice in localStorage.
 */
function ThemeProvider({
  children,
  defaultTheme = "violet-forge",
  defaultMode = "dark",
  themes: themesProp,
  storageKey = "theo-ui:theme",
}: ThemeProviderProps): JSX.Element {
  // Merge user themes with the default, dedup by name (user wins).
  const mergedThemes = useMemo<Theme[]>(() => {
    const base = [violetForge];
    const extras = themesProp ?? [];
    const map = new Map<string, Theme>();
    for (const t of base) map.set(t.name, t);
    for (const t of extras) map.set(t.name, t);
    return Array.from(map.values());
  }, [themesProp]);

  const [themes, setThemes] = useState<Theme[]>(mergedThemes);

  // Re-sync state when the `themes` prop changes between renders. Avoids the
  // common pitfall where the user passes a different array later and the
  // initial-state-only seed silently ignores the change.
  useEffect(() => {
    setThemes(mergedThemes);
  }, [mergedThemes]);

  const [themeName, setThemeName] = useState<string>(() => {
    if (typeof window === "undefined" || !storageKey) return defaultTheme;
    try {
      return window.localStorage.getItem(`${storageKey}:name`) ?? defaultTheme;
    } catch {
      return defaultTheme;
    }
  });

  const [mode, setModeState] = useState<ThemeMode>(() => {
    if (typeof window === "undefined" || !storageKey) return defaultMode;
    try {
      const stored = window.localStorage.getItem(`${storageKey}:mode`);
      return stored === "dark" || stored === "light" ? stored : defaultMode;
    } catch {
      return defaultMode;
    }
  });

  // Inject CSS vars whenever the themes list changes.
  useEffect(() => {
    injectThemeCss(themes);
  }, [themes]);

  // Apply data-theme + data-mode to <html>, load fonts.
  useEffect(() => {
    if (typeof document === "undefined") return;
    const active = themes.find((t) => t.name === themeName) ?? themes[0];
    if (!active) return;
    document.documentElement.setAttribute("data-theme", active.name);
    document.documentElement.setAttribute("data-mode", mode);
    document.documentElement.classList.toggle("dark", mode === "dark");
    loadThemeFonts(active);
  }, [themeName, mode, themes]);

  // Persist on change.
  useEffect(() => {
    if (typeof window === "undefined" || !storageKey) return;
    try {
      window.localStorage.setItem(`${storageKey}:name`, themeName);
      window.localStorage.setItem(`${storageKey}:mode`, mode);
    } catch {
      /* storage may fail in private mode; not critical */
    }
  }, [themeName, mode, storageKey]);

  const setTheme = useCallback((name: string) => setThemeName(name), []);
  const setMode = useCallback((next: ThemeMode) => setModeState(next), []);
  const toggleMode = useCallback(
    () => setModeState((cur) => (cur === "light" ? "dark" : "light")),
    [],
  );
  const registerTheme = useCallback((theme: Theme) => {
    setThemes((cur) => {
      const idx = cur.findIndex((t) => t.name === theme.name);
      if (idx >= 0) {
        const next = cur.slice();
        next[idx] = theme;
        return next;
      }
      return [...cur, theme];
    });
  }, []);

  const active = themes.find((t) => t.name === themeName) ?? themes[0] ?? violetForge;

  const value = useMemo<ThemeContextValue>(
    () => ({
      theme: active,
      mode,
      themes,
      setTheme,
      setMode,
      toggleMode,
      registerTheme,
    }),
    [active, mode, themes, setTheme, setMode, toggleMode, registerTheme],
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

/**
 * useTheme — access theme state from any component inside <ThemeProvider>.
 * Throws if used outside the provider — fail-fast.
 */
function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (!ctx) {
    throw new Error("useTheme must be used inside <ThemeProvider>.");
  }
  return ctx;
}

export { ThemeProvider, useTheme };

import * as DropdownMenu from "@radix-ui/react-dropdown-menu";
import { Check, Moon, Palette, Sun } from "lucide-react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";
import { useTheme } from "@/themes/theme-provider";

interface ThemeSwitcherProps {
  className?: string;
  /** If true, renders mode toggle inline next to the theme menu. */
  showModeToggle?: boolean;
}

/**
 * ThemeSwitcher — drop-in theme + mode picker.
 *
 * Two affordances:
 *   - Palette dropdown lists all registered themes with the active marked.
 *   - Optional sun/moon button toggles light/dark.
 *
 * Stateless wrt itself — pulls state from `useTheme()`.
 */
function ThemeSwitcher({ className, showModeToggle = true }: ThemeSwitcherProps): JSX.Element {
  const { theme, themes, setTheme, mode, toggleMode } = useTheme();

  return (
    <div className={cn("inline-flex items-center gap-1", className)}>
      <DropdownMenu.Root>
        <DropdownMenu.Trigger asChild>
          <button
            type="button"
            aria-label={`Theme: ${theme.label}`}
            className={cn(
              "inline-flex h-9 items-center gap-2 rounded-lg border border-border/60 bg-card px-3",
              "font-medium font-sans text-body-sm text-foreground",
              "transition-colors hover:bg-muted",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            )}
          >
            <Palette className="size-4 text-primary" aria-hidden="true" />
            <span>{theme.label}</span>
          </button>
        </DropdownMenu.Trigger>
        <DropdownMenu.Portal>
          <DropdownMenu.Content
            align="end"
            sideOffset={6}
            className={cn(
              "z-50 min-w-[16rem] overflow-hidden rounded-lg border bg-popover p-1 text-popover-foreground shadow-md",
              "data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=open]:animate-in",
              "data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=closed]:animate-out",
            )}
          >
            {themes.map((t) => (
              <DropdownMenu.Item
                key={t.name}
                onSelect={() => setTheme(t.name)}
                className={cn(
                  "flex cursor-pointer items-start justify-between gap-3 rounded-md px-2 py-2",
                  "focus:bg-muted focus:outline-none data-[highlighted]:bg-muted",
                )}
              >
                <span className="flex min-w-0 flex-col">
                  <span className="font-medium text-body-sm">{t.label}</span>
                  {t.description ? (
                    <span className="text-body-sm text-muted-foreground">{t.description}</span>
                  ) : null}
                </span>
                {t.name === theme.name ? (
                  <Check className="mt-1 size-4 shrink-0 text-primary" aria-hidden="true" />
                ) : null}
              </DropdownMenu.Item>
            ))}
          </DropdownMenu.Content>
        </DropdownMenu.Portal>
      </DropdownMenu.Root>

      {showModeToggle ? (
        <button
          type="button"
          onClick={toggleMode}
          aria-label={`Switch to ${mode === "light" ? "dark" : "light"} mode`}
          className={cn(
            "inline-flex size-9 items-center justify-center rounded-lg border border-border/60 bg-card",
            "text-foreground transition-colors hover:bg-muted",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          )}
        >
          {mode === "light" ? <Moon className="size-4" /> : <Sun className="size-4" />}
        </button>
      ) : null}
    </div>
  );
}

export { ThemeSwitcher };

export type { ColorScale, Theme, ThemeFonts, ThemeMode } from "@/themes/types";
export { ThemeProvider, useTheme } from "@/themes/theme-provider";
export { ThemeScript } from "@/themes/theme-script";
export { ThemeSwitcher } from "@/themes/theme-switcher";
export { violetForge } from "@/themes/violet-forge";
export { classicPaper } from "@/themes/classic-paper";
export { auroraTerminal } from "@/themes/aurora-terminal";

import { auroraTerminal } from "@/themes/aurora-terminal";
import { classicPaper } from "@/themes/classic-paper";
import { violetForge } from "@/themes/violet-forge";

/**
 * All themes bundled with Theo UI. Pass to `<ThemeProvider themes={builtinThemes}>`
 * if you want all of them available out of the box.
 */
export const builtinThemes = [violetForge, classicPaper, auroraTerminal];
